package com.cq.maintenance.system;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
import com.cq.maintenance.common.exception.BusinessException;import com.cq.maintenance.security.LoginUser;import com.cq.maintenance.system.dto.*;import com.cq.maintenance.system.entity.SysUser;import com.cq.maintenance.system.mapper.UserManagementMapper;import com.cq.maintenance.system.service.UserManagementService;import java.util.List;import org.junit.jupiter.api.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.crypto.password.PasswordEncoder;
class UserManagementServiceTest {UserManagementMapper mapper;PasswordEncoder encoder;UserManagementService service;@BeforeEach void setUp(){mapper=mock(UserManagementMapper.class);encoder=mock(PasswordEncoder.class);service=new UserManagementService(mapper,encoder);when(mapper.countRole(1L)).thenReturn(1L);when(encoder.encode(anyString())).thenReturn("$2a$hashed");doAnswer(i->{((SysUser)i.getArgument(0)).setId(9L);return 1;}).when(mapper).insert(any());LoginUser user=new LoginUser(1L,"admin","管理员","ENABLED",List.of("ADMIN"),List.of(),List.of(),null,List.of());SecurityContextHolder.getContext().setAuthentication(UsernamePasswordAuthenticationToken.authenticated(user,null,List.of()));}@AfterEach void clear(){SecurityContextHolder.clearContext();}
 @Test void createHashesPasswordAndAssignsRelations(){Long id=service.create(new UserCreateRequest("new_user","Password1","新用户",null,null,"工程师",null,null,List.of(1L),List.of()));assertEquals(9L,id);verify(encoder).encode("Password1");verify(mapper).insertRoles(9L,List.of(1L));}
 @Test void duplicateUsernameIsRejected(){when(mapper.countUsername("new_user")).thenReturn(1L);assertThrows(BusinessException.class,()->service.create(new UserCreateRequest("new_user","Password1","新用户",null,null,null,null,null,List.of(1L),List.of())));verify(encoder,never()).encode(anyString());}
 @Test void cannotDisableCurrentUser(){SysUser user=new SysUser();user.setId(1L);user.setStatus("ENABLED");when(mapper.find(1L)).thenReturn(user);assertThrows(BusinessException.class,()->service.status(1L,new UserStatusRequest("DISABLED")));verify(mapper,never()).updateStatus(anyLong(),anyString());}
}
